223	+// Drain everything readable on `fd` into `buf`, delivering each completed
224	+// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
225	+// error so the caller stops polling that stream.
226	+bool pump_stream(int fd, int stream, std::string& buf,
227	+                 const std::function<void(int, std::string_view)>& on_line) {
228	+  char rb[4096];
229	+  const ssize_t n = read(fd, rb, sizeof rb);
230	+  if (n == 0) return false;          // EOF: child closed this stream
231	+  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
232	+  buf.append(rb, static_cast<size_t>(n));
233	+  size_t nl;
234	+  while ((nl = buf.find('\n')) != std::string::npos) {
235	+    on_line(stream, std::string_view(buf.data(), nl));
236	+    buf.erase(0, nl + 1);
237	+  }
238	+  return true;
239	+}
240	+
241	+}  // namespace
