243	+int run_line_filtered(
244	+    const std::vector<std::string>& argv,
245	+    const std::function<void(int, std::string_view)>& on_line) {
246	+  if (argv.empty()) return -1;
247	+
248	+  int out_fds[2], err_fds[2];
249	+  if (pipe(out_fds) != 0) return -1;
250	+  if (pipe(err_fds) != 0) {
251	+    close(out_fds[0]);
252	+    close(out_fds[1]);
253	+    return -1;
254	+  }
255	+
256	+  pid_t pid = fork();
257	+  if (pid < 0) {
258	+    close(out_fds[0]);
259	+    close(out_fds[1]);
260	+    close(err_fds[0]);
261	+    close(err_fds[1]);
262	+    return -1;
263	+  }
264	+
265	+  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
266	+    close(out_fds[0]);
267	+    close(err_fds[0]);
268	+    dup2(out_fds[1], STDOUT_FILENO);
269	+    dup2(err_fds[1], STDERR_FILENO);
270	+    if (out_fds[1] > 2) close(out_fds[1]);
271	+    if (err_fds[1] > 2) close(err_fds[1]);
272	+    std::vector<char*> cargv;
273	+    cargv.reserve(argv.size() + 1);
274	+    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
275	+    cargv.push_back(nullptr);
276	+    execvp(cargv[0], cargv.data());
277	+    _exit(127);  // exec failed
278	+  }
279	+
280	+  // parent: poll both pipes, line-buffer each, until both hit EOF. No timeout --
281	+  // matches exec_passthrough (a cycle run can be arbitrarily long).
282	+  close(out_fds[1]);
283	+  close(err_fds[1]);
284	+  int fd[2] = {out_fds[0], err_fds[0]};
285	+  const int stream[2] = {1, 2};
286	+  std::string buf[2];
287	+  bool open_[2] = {true, true};
288	+
289	+  while (open_[0] || open_[1]) {
290	+    struct pollfd pfd[2];
291	+    int idx[2];
292	+    int n = 0;
293	+    for (int i = 0; i < 2; ++i)
294	+      if (open_[i]) {
295	+        pfd[n] = {fd[i], POLLIN, 0};
296	+        idx[n] = i;
297	+        ++n;
298	+      }
299	+    if (poll(pfd, n, -1) < 0) {
300	+      if (errno == EINTR) continue;
301	+      break;
302	+    }
303	+    for (int k = 0; k < n; ++k) {
304	+      const int i = idx[k];
305	+      if (pfd[k].revents & (POLLIN | POLLHUP | POLLERR))
306	+        if (!pump_stream(fd[i], stream[i], buf[i], on_line)) open_[i] = false;
307	+    }
308	+  }
309	+  // Flush any final line that arrived without a trailing newline.
310	+  for (int i = 0; i < 2; ++i)
311	+    if (!buf[i].empty()) on_line(stream[i], buf[i]);
312	+
313	+  close(fd[0]);
314	+  close(fd[1]);
315	+  int status = 0;
316	+  waitpid(pid, &status, 0);
317	+  if (WIFEXITED(status)) return WEXITSTATUS(status);
318	+  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
319	+  return -1;
320	+}
321	+
