551	+// Presentation filter for a cycle-accurate engine's raw output.
552	+//
553	+// `run --mode cycle` runs vsim standalone, which is chatty: it prints a startup
554	+// banner (Copyright / Version) on stdout -- interleaved with the program's own
555	+// stdout -- and verbose `[info]` log lines on stderr, including the headline
556	+// "<N> cycles simulated" count. The user wants only the program's output and
557	+// that count (restated as andesim's own one-line result), with vsim's banner
558	+// and log hidden.
559	+//
560	+// VsimFilter classifies each output line, in arrival order, into drop / stdout /
561	+// stderr, and lifts the cycle count out of the otherwise-hidden log so the
562	+// driver can re-print it under its own [andesim] prefix. The logic is pure (no
563	+// I/O); the spawn/relay loop that feeds it lives in process.cpp.
564	+#ifndef ANDESIM_VSIM_FILTER_HPP
565	+#define ANDESIM_VSIM_FILTER_HPP
566	+
567	+#include <cstdint>
568	+#include <optional>
569	+#include <string>
570	+#include <string_view>
571	+
572	+namespace andes_sim {
573	+
574	+// Lift the count from vsim's "<N> cycles simulated" log line, e.g.
575	+// "[info] 3573 cycles simulated" -> 3573. Returns nullopt for any other line.
576	+// Matches on the "<digits> cycles simulated" shape, tolerant of the leading
577	+// "[info]" tag and surrounding spaces, so it never mistakes the neighbouring
578	+// "[info] 0.354s elapsed, ...Hz" timing line for a count.
579	+std::optional<uint64_t> parse_cycles_line(std::string_view line);
580	+
581	+// Decides how each line of a cycle-accurate engine's output is presented.
582	+// Feed lines in arrival order with their source stream (1 = stdout, 2 = stderr),
583	+// excluding the trailing newline:
584	+//   - vsim's startup banner (Copyright / Version, plus its trailing blank line)
585	+//     is dropped,
586	+//   - every `[info]` log line is dropped,
587	+//   - the "<N> cycles simulated" line is dropped but its count is lifted into
588	+//     cycles() for the driver to re-print, and
589	+//   - everything else passes through -- the program's own stdout, and any real
590	+//     diagnostic vsim logs above info level ([warn]/[error]/...) on stderr.
591	+// Stateful: it tracks when the banner has ended (the first real stdout line), so
592	+// a "Version :" the program itself prints later is NOT mistaken for the banner.
593	+class VsimFilter {
594	+ public:
595	+  enum class Dest { kDrop, kStdout, kStderr };
596	+
597	+  Dest classify(int stream, std::string_view line);
598	+
599	+  // The lifted "N cycles simulated" count, once a matching line has been seen.
600	+  std::optional<uint64_t> cycles() const { return cycles_; }
601	+
602	+ private:
603	+  std::optional<uint64_t> cycles_;
604	+  bool seen_program_output_ = false;  // stdout: false until the banner ends
605	+};
606	+
607	+// Strip vsim's startup banner from a captured stdout buffer, returning what
608	+// remains (the program's own output). The buffer-mode counterpart to VsimFilter
609	+// for the hybrid relay: the vsim leg's stdout was captured whole (its [info] log
610	+// already dropped at capture), so only the banner needs removing -- the same
611	+// Copyright / Version / leading-blank rule, applied line by line. A final line
612	+// without a trailing newline is preserved without one.
613	+std::string strip_vsim_banner(std::string_view buf);
614	+
615	+}  // namespace andes_sim
616	+
617	+#endif  // ANDESIM_VSIM_FILTER_HPP
